 20→// Handler holds the vault reference and provides <NAME_2> handler methods
 21→type Handler struct {
 22→	vault  *vault.Vault
 23→	logger *slog.Logger
 24→}
 25→
 26→// New creates a new Handler with the given Vault and Logger
 27→func New(v *vault.Vault, logger *slog.Logger) *Handler {
 28→	if logger == nil {
 29→		logger = slog.New(slog.NewTextHandler(io.Discard, nil))
 30→	}
 31→	return &Handler{vault: v, logger: logger}
 32→}
