 34→// SearchNotes implements the search_notes tool
 35→func (h *Handler) SearchNotes(ctx context.Context, req *mcp.CallToolRequest, input note.SearchNotesInput) (*mcp.CallToolResult, note.SearchNotesOutput, error) {
 36→	var results []string
 37→	query := input.Query
 38→
 39→	// Use case-insensitive literal matching via regexp.QuoteMeta to prevent
 40→	// regex injection from user-provided queries
 41→	re := regexp.MustCompile("(?i)" + regexp.QuoteMeta(query))
 42→
 43→	// Walk through the vault directory
 44→	err := filepath.Walk(h.vault.Path, func(path string, info os.FileInfo, err error) error {
 45→		if ctx.Err() != nil {
 46→			return ctx.Err()
 47→		}
 48→
 49→		if err != nil {
 50→			h.logger.Debug("skipping path", "path", path, "error", err)
 51→			return nil
 52→		}
 53→
 54→		// Skip directories
 55→		if info.IsDir() {
 56→			// Check if directory is allowed (not hidden)
 57→			allowed, checkErr := h.vault.IsPathAllowed(path)
 58→			if checkErr != nil || !allowed {
 59→				return filepath.SkipDir
 60→			}
 61→			return nil
 62→		}
 63→
 64→		// Only process markdown files
 65→		if !strings.HasSuffix(strings.ToLower(path), ".md") {
 66→			return nil
 67→		}
 68→
 69→		// Check if file is allowed
 70→		allowed, checkErr := h.vault.IsPathAllowed(path)
 71→		if checkErr != nil || !allowed {
 72→			return nil
 73→		}
 74→
 75→		// Get filename
 76→		filename := filepath.Base(path)
 77→
 78→		if re.MatchString(filename) {
 79→			results = append(results, path)
 80→			// Limit results
 81→			if len(results) >= vault.MaxSearchResults {
 82→				return filepath.SkipAll
 83→			}
 84→		}
 85→
 86→		return nil
 87→	})
 88→
 89→	if err != nil {
 90→		return nil, note.SearchNotesOutput{}, fmt.Errorf("failed to search notes: %w", err)
 91→	}
 92→
 93→	output := note.SearchNotesOutput{
 94→		Results: results,
 95→	}
 96→
 97→	// Create text content for the result
 98→	textContent := fmt.Sprintf("Found %d matching notes", len(results))
 99→	if len(results) > 0 {
100→		textContent += ":\n" + strings.Join(results, "\n")
101→	}
102→
103→	result := &mcp.CallToolResult{
104→		Content: []mcp.Content{
105→			&mcp.TextContent{
106→				Text: textContent,
107→			},
108→		},
109→	}
110→
111→	return result, output, nil
112→}
