178→// CreateNote implements the create_note tool
179→func (h *Handler) CreateNote(ctx context.Context, req *mcp.CallToolRequest, input note.CreateNoteInput) (*mcp.CallToolResult, note.CreateNoteOutput, error) {
180→	if input.Title == "" {
181→		return nil, note.CreateNoteOutput{}, fmt.Errorf("title is required")
182→	}
183→
184→	if len(input.Content) > vault.MaxContentSize {
185→		return nil, note.CreateNoteOutput{}, fmt.Errorf("content too large: %d bytes exceeds limit of %d", len(input.Content), vault.MaxContentSize)
186→	}
187→
188→	slug := note.Slugify(input.Title)
189→	if slug == "" {
190→		return nil, note.CreateNoteOutput{}, fmt.Errorf("title produces an empty slug")
191→	}
192→
193→	today := time.Now().Format("2006-01-02")
194→	filename := today + "_" + slug + ".md"
195→
196→	dir := h.vault.Path
197→	if input.Folder != "" {
198→		dir = filepath.Join(h.vault.Path, input.Folder)
199→	}
200→
201→	fullPath := filepath.Join(dir, filename)
202→
203→	allowed, err := h.vault.IsPathAllowed(fullPath)
204→	if err != nil {
205→		return nil, note.CreateNoteOutput{}, fmt.Errorf("path validation error: %w", err)
206→	}
207→	if !allowed {
208→		return nil, note.CreateNoteOutput{}, fmt.Errorf("access denied: path is outside vault or is a hidden file")
209→	}
210→
211→	if err := os.MkdirAll(dir, 0755); err != nil {
212→		return nil, note.CreateNoteOutput{}, fmt.Errorf("failed to create directory: %w", err)
213→	}
214→
215→	frontmatter := note.GenerateFrontmatter(input.Tags, today, today)
216→
217→	var content strings.Builder
218→	content.WriteString(frontmatter)
219→	content.WriteString("\n# ")
220→	content.WriteString(input.Title)
221→	content.WriteByte('\n')
222→	if input.Content != "" {
223→		content.WriteByte('\n')
224→		content.WriteString(input.Content)
225→		content.WriteByte('\n')
226→	}
227→
228→	// Use O_CREATE|O_EXCL to atomically fail if file already exists (prevents TOCTOU)
229→	f, err := os.OpenFile(fullPath, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0644)
230→	if err != nil {
231→		if os.IsExist(err) {
232→			return nil, note.CreateNoteOutput{}, fmt.Errorf("file already exists: %s", fullPath)
233→		}
234→		return nil, note.CreateNoteOutput{}, fmt.Errorf("failed to create file: %w", err)
235→	}
236→	_, writeErr := f.WriteString(content.String())
237→	closeErr := f.Close()
238→	if writeErr != nil {
239→		return nil, note.CreateNoteOutput{}, fmt.Errorf("failed to write file: %w", writeErr)
240→	}
241→	if closeErr != nil {
242→		return nil, note.CreateNoteOutput{}, fmt.Errorf("failed to close file: %w", closeErr)
243→	}
244→
245→	output := note.CreateNoteOutput{Path: fullPath}
246→	result := &mcp.CallToolResult{
247→		Content: []mcp.Content{
248→			&mcp.TextContent{Text: fmt.Sprintf("Created note: %s", fullPath)},
249→		},
250→	}
251→	return result, output, nil
252→}
