254→// UpdateNote implements the update_note tool
255→func (h *Handler) UpdateNote(ctx context.Context, req *mcp.CallToolRequest, input note.UpdateNoteInput) (*mcp.CallToolResult, note.UpdateNoteOutput, error) {
256→	if len(input.Content) > vault.MaxContentSize {
257→		return nil, note.UpdateNoteOutput{}, fmt.Errorf("content too large: %d bytes exceeds limit of %d", len(input.Content), vault.MaxContentSize)
258→	}
259→
260→	allowed, err := h.vault.IsPathAllowed(input.Path)
261→	if err != nil {
262→		return nil, note.UpdateNoteOutput{}, fmt.Errorf("path validation error: %w", err)
263→	}
264→	if !allowed {
265→		return nil, note.UpdateNoteOutput{}, fmt.Errorf("access denied: path is outside vault or is a hidden file")
266→	}
267→
268→	if _, err := os.Stat(input.Path); os.IsNotExist(err) {
269→		return nil, note.UpdateNoteOutput{}, fmt.Errorf("file does not exist: %s", input.Path)
270→	} else if err != nil {
271→		return nil, note.UpdateNoteOutput{}, fmt.Errorf("failed to stat file: %w", err)
272→	}
273→
274→	mode := input.Mode
275→	if mode == "" {
276→		mode = "replace"
277→	}
278→
279→	switch mode {
280→	case "replace":
281→		if err := os.WriteFile(input.Path, []byte(input.Content), 0644); err != nil {
282→			return nil, note.UpdateNoteOutput{}, fmt.Errorf("failed to write file: %w", err)
283→		}
284→	case "append":
285→		f, err := os.OpenFile(input.Path, os.O_WRONLY|os.O_APPEND, 0644)
286→		if err != nil {
287→			return nil, note.UpdateNoteOutput{}, fmt.Errorf("failed to open file for append: %w", err)
288→		}
289→		_, writeErr := f.WriteString("\n\n" + input.Content)
290→		closeErr := f.Close()
291→		if writeErr != nil {
292→			return nil, note.UpdateNoteOutput{}, fmt.Errorf("failed to append to file: %w", writeErr)
293→		}
294→		if closeErr != nil {
295→			return nil, note.UpdateNoteOutput{}, fmt.Errorf("failed to close file: %w", closeErr)
296→		}
297→	default:
298→		return nil, note.UpdateNoteOutput{}, fmt.Errorf("invalid mode: %s (must be 'replace' or 'append')", mode)
299→	}
300→
301→	output := note.UpdateNoteOutput{Path: input.Path}
302→	result := &mcp.CallToolResult{
303→		Content: []mcp.Content{
304→			&mcp.TextContent{Text: fmt.Sprintf("Updated note (%s): %s", mode, input.Path)},
305→		},
306→	}
307→	return result, output, nil
308→}
