  7→	"strings"
  8→)
  9→
 10→// MaxSearchResults limits the number of search results to prevent excessive output
 11→const MaxSearchResults = 200
 12→
 13→// MaxReadPaths limits the number of paths that can be read in a single ReadNotes call
 14→const MaxReadPaths = 100
 15→
 16→// MaxContentSize limits the size of note content to prevent memory/disk exhaustion (10 MB)
 17→const MaxContentSize = 10 * 1024 * 1024
