 19→// Vault represents an Obsidian vault directory with path validation
 20→type Vault struct {
 21→	Path string // resolved absolute path to the vault root
 22→}
 23→
 24→// New creates a new Vault, expanding ~ and resolving to an absolute path.
 25→// Returns an error if the vault directory does not exist.
 26→func New(rawPath string) (*Vault, error) {
 27→	path := rawPath
 28→
 29→	// Expand home directory
 30→	if strings.HasPrefix(path, "~") {
 31→		home, err := os.UserHomeDir()
 32→		if err != nil {
 33→			return nil, fmt.Errorf("failed to get home directory: %w", err)
 34→		}
 35→		path = filepath.Join(home, path[1:])
 36→	}
 37→
 38→	// Resolve to absolute path
 39→	absPath, err := filepath.Abs(path)
 40→	if err != nil {
 41→		return nil, fmt.Errorf("failed to resolve absolute path: %w", err)
 42→	}
 43→	path = absPath
 44→
 45→	// Check if vault path exists and is a directory
 46→	info, err := os.Stat(path)
 47→	if err != nil {
 48→		return nil, fmt.Errorf("vault path error: %w", err)
 49→	}
 50→	if !info.IsDir() {
 51→		return nil, fmt.Errorf("vault path is not a directory: %s", path)
 52→	}
 53→
 54→	return &Vault{Path: path}, nil
 55→}
 56→
 57→// IsPathAllowed checks if a given path is within the allowed vault directory
 58→// and doesn't access hidden files or directories
 59→func (v *Vault) IsPathAllowed(path string) (bool, error) {
 60→	// Expand home directory
 61→	if strings.HasPrefix(path, "~") {
 62→		home, err := os.UserHomeDir()
 63→		if err != nil {
 64→			return false, fmt.Errorf("failed to get home directory: %w", err)
 65→		}
 66→		path = filepath.Join(home, path[1:])
 67→	}
 68→
 69→	// Get absolute path
 70→	absPath, err := filepath.Abs(path)
 71→	if err != nil {
 72→		return false, fmt.Errorf("failed to get absolute path: %w", err)
 73→	}
 74→
 75→	// Resolve symlinks
 76→	resolvedPath, err := filepath.EvalSymlinks(absPath)
 77→	if err != nil {
 78→		// If the path doesn't exist, walk up to the nearest existing
 79→		// ancestor, resolve its symlinks, then re-append the remainder.
 80→		if os.IsNotExist(err) {
 81→			resolvedPath = resolveWithAncestors(absPath)
 82→		} else {
 83→			return false, fmt.Errorf("failed to resolve symlinks: %w", err)
 84→		}
 85→	}
 86→
 87→	// Get absolute vault path
 88→	absVaultPath, err := filepath.Abs(v.Path)
 89→	if err != nil {
 90→		return false, fmt.Errorf("failed to get absolute vault path: %w", err)
 91→	}
 92→
 93→	// Resolve vault symlinks
 94→	resolvedVaultPath, err := filepath.EvalSymlinks(absVaultPath)
 95→	if err != nil {
 96→		if !os.IsNotExist(err) {
 97→			return false, fmt.Errorf("failed to resolve vault symlinks: %w", err)
 98→		}
 99→		resolvedVaultPath = resolveWithAncestors(absVaultPath)
100→	}
101→
102→	// Clean paths
103→	cleanPath := filepath.Clean(resolvedPath)
104→	cleanVaultPath := filepath.Clean(resolvedVaultPath)
105→
106→	// Check if path is within vault (ensure separator boundary to prevent
107→	// prefix false-positives like /tmp/vault matching /tmp/vault-evil)
108→	if cleanPath != cleanVaultPath && !strings.HasPrefix(cleanPath, cleanVaultPath+string(filepath.Separator)) {
109→		return false, nil
110→	}
111→
112→	// Check for hidden files/directories
113→	relPath, err := filepath.Rel(cleanVaultPath, cleanPath)
114→	if err != nil {
115→		return false, fmt.Errorf("failed to get relative path: %w", err)
116→	}
117→
118→	pathParts := strings.SplitSeq(relPath, string(filepath.Separator))
119→	for part := range pathParts {
120→		if strings.HasPrefix(part, ".") && part != "." && part != ".." {
121→			return false, nil
122→		}
123→	}
124→
125→	return true, nil
126→}
127→
128→// resolveWithAncestors resolves symlinks by walking up to the nearest existing
129→// ancestor directory and re-appending the remaining path segments.
130→func resolveWithAncestors(absPath string) string {
131→	current := absPath
132→	var tail []string
133→	for {
134→		resolved, err := filepath.EvalSymlinks(current)
135→		if err == nil {
136→			// Found an existing ancestor — rejoin the tail
137→			for i := len(tail) - 1; i >= 0; i-- {
138→				resolved = filepath.Join(resolved, tail[i])
139→			}
140→			return resolved
141→		}
142→		parent := filepath.Dir(current)
143→		if parent == current {
144→			// Reached filesystem root without finding existing path
145→			return absPath
146→		}
147→		tail = append(tail, filepath.Base(current))
148→		current = parent
149→	}
150→}
