432→// GetBacklinks implements the get_backlinks tool
433→func (h *Handler) GetBacklinks(ctx context.Context, req *mcp.CallToolRequest, input note.GetBacklinksInput) (*mcp.CallToolResult, note.GetBacklinksOutput, error) {
434→	if input.NoteName == "" {
435→		return nil, note.GetBacklinksOutput{}, fmt.Errorf("note_name is required")
436→	}
437→
438→	noteName := strings.TrimSuffix(input.NoteName, ".md")
439→	wikilinkRe := regexp.MustCompile(`\[\[([^\]|]+)(?:\|[^\]]+)?\]\]`)
440→
441→	var results []note.Backlink
442→
443→	err := filepath.Walk(h.vault.Path, func(path string, info os.FileInfo, err error) error {
444→		if ctx.Err() != nil {
445→			return ctx.Err()
446→		}
447→
448→		if err != nil {
449→			h.logger.Debug("skipping path", "path", path, "error", err)
450→			return nil
451→		}
452→
453→		if info.IsDir() {
454→			allowed, checkErr := h.vault.IsPathAllowed(path)
455→			if checkErr != nil || !allowed {
456→				return filepath.SkipDir
457→			}
458→			return nil
459→		}
460→
461→		if !strings.HasSuffix(strings.ToLower(path), ".md") {
462→			return nil
463→		}
464→
465→		allowed, checkErr := h.vault.IsPathAllowed(path)
466→		if checkErr != nil || !allowed {
467→			return nil
468→		}
469→
470→		// Exclude the target note itself
471→		baseName := strings.TrimSuffix(filepath.Base(path), ".md")
472→		if strings.EqualFold(baseName, noteName) {
473→			return nil
474→		}
475→
476→		data, err := os.ReadFile(path)
477→		if err != nil {
478→			h.logger.Debug("skipping unreadable file", "path", path, "error", err)
479→			return nil
480→		}
481→
482→		lines := strings.SplitSeq(string(data), "\n")
483→		for line := range lines {
484→			matches := wikilinkRe.FindAllStringSubmatch(line, -1)
485→			for _, match := range matches {
486→				if len(match) >= 2 {
487→					linkTarget := strings.TrimSuffix(match[1], ".md")
488→					if strings.EqualFold(linkTarget, noteName) {
489→						results = append(results, note.Backlink{
490→							Path: path,
491→							Line: line,
492→						})
493→						break // one match per line is enough
494→					}
495→				}
496→			}
497→		}
498→
499→		return nil
500→	})
501→
502→	if err != nil {
503→		return nil, note.GetBacklinksOutput{}, fmt.Errorf("failed to search backlinks: %w", err)
504→	}
505→
506→	output := note.GetBacklinksOutput{Results: results}
507→
508→	textContent := fmt.Sprintf("Found %d backlinks to [[%s]]", len(results), noteName)
509→	if len(results) > 0 {
510→		var lines []string
511→		for _, bl := range results {
512→			lines = append(lines, fmt.Sprintf("%s: %s", bl.Path, bl.Line))
513→		}
514→		textContent += ":\n" + strings.Join(lines, "\n")
515→	}
516→
517→	result := &mcp.CallToolResult{
518→		Content: []mcp.Content{
519→			&mcp.TextContent{Text: textContent},
520→		},
521→	}
522→	return result, output, nil
523→}
