525→// ListTags implements the list_tags tool
526→func (h *Handler) ListTags(ctx context.Context, req *mcp.CallToolRequest, input note.ListTagsInput) (*mcp.CallToolResult, note.ListTagsOutput, error) {
527→	tagCounts := make(map[string]int)
528→
529→	// Regex for inline #tags (not inside code blocks)
530→	inlineTagRe := regexp.MustCompile(`(?:^|\s)#([a-zA-Z][a-zA-Z0-9_/-]*)`)
531→
532→	err := filepath.Walk(h.vault.Path, func(path string, info os.FileInfo, err error) error {
533→		if ctx.Err() != nil {
534→			return ctx.Err()
535→		}
536→
537→		if err != nil {
538→			h.logger.Debug("skipping path", "path", path, "error", err)
539→			return nil
540→		}
541→
542→		if info.IsDir() {
543→			allowed, checkErr := h.vault.IsPathAllowed(path)
544→			if checkErr != nil || !allowed {
545→				return filepath.SkipDir
546→			}
547→			return nil
548→		}
549→
550→		if !strings.HasSuffix(strings.ToLower(path), ".md") {
551→			return nil
552→		}
553→
554→		allowed, checkErr := h.vault.IsPathAllowed(path)
555→		if checkErr != nil || !allowed {
556→			return nil
557→		}
558→
559→		data, err := os.ReadFile(path)
560→		if err != nil {
561→			h.logger.Debug("skipping unreadable file", "path", path, "error", err)
562→			return nil
563→		}
564→
565→		content := string(data)
566→
567→		// Parse frontmatter tags
568→		if strings.HasPrefix(content, "---\n") {
569→			endIdx := strings.Index(content[4:], "\n---\n")
570→			if endIdx >= 0 {
571→				frontmatter := content[4 : 4+endIdx]
572→				note.ParseFrontmatterTags(frontmatter, tagCounts)
573→			}
574→		}
575→
576→		// Parse inline #tags (skip code blocks)
577→		lines := strings.Split(content, "\n")
578→		inCodeBlock := false
579→		for _, line := range lines {
580→			if strings.HasPrefix(strings.TrimSpace(line), "```") {
581→				inCodeBlock = !inCodeBlock
582→				continue
583→			}
584→			if inCodeBlock {
585→				continue
586→			}
587→			matches := inlineTagRe.FindAllStringSubmatch(line, -1)
588→			for _, match := range matches {
589→				if len(match) >= 2 {
590→					tagCounts[match[1]]++
591→				}
592→			}
593→		}
594→
595→		return nil
596→	})
597→
598→	if err != nil {
599→		return nil, note.ListTagsOutput{}, fmt.Errorf("failed to list tags: %w", err)
600→	}
601→
602→	// Filter by prefix and sort
603→	var tags []note.TagCount
604→	for tag, count := range tagCounts {
605→		if input.Prefix == "" || strings.HasPrefix(tag, input.Prefix) {
606→			tags = append(tags, note.TagCount{Tag: tag, Count: count})
607→		}
608→	}
609→	sort.Slice(tags, func(i, j int) bool {
610→		return tags[i].Tag < tags[j].Tag
611→	})
612→
613→	output := note.ListTagsOutput{Tags: tags}
614→
615→	textContent := fmt.Sprintf("Found %d unique tags", len(tags))
616→	if len(tags) > 0 {
617→		var lines []string
618→		for _, tc := range tags {
619→			lines = append(lines, fmt.Sprintf("#%s (%d)", tc.Tag, tc.Count))
620→		}
621→		textContent += ":\n" + strings.Join(lines, "\n")
622→	}
623→
624→	result := &mcp.CallToolResult{
625→		Content: []mcp.Content{
626→			&mcp.TextContent{Text: textContent},
627→		},
628→	}
629→	return result, output, nil
630→}
