 19→// Vault represents an Obsidian vault directory with path validation
 20→type Vault struct {
 21→	Path string // resolved absolute path to the vault root
 22→}
 23→
 24→// New creates a new Vault, expanding ~ and resolving to an absolute path.
 25→// Returns an error if the vault directory does not exist.
 26→func New(rawPath string) (*Vault, error) {
 27→	path := rawPath
 28→
 29→	// Expand home directory
 30→	if strings.HasPrefix(path, "~") {
 31→		home, err := os.UserHomeDir()
 32→		if err != nil {
 33→			return nil, fmt.Errorf("failed to get home directory: %w", err)
 34→		}
 35→		path = filepath.Join(home, path[1:])
 36→	}
 37→
 38→	// Resolve to absolute path
 39→	absPath, err := filepath.Abs(path)
 40→	if err != nil {
 41→		return nil, fmt.Errorf("failed to resolve absolute path: %w", err)
 42→	}
 43→	path = absPath
 44→
 45→	// Check if vault path exists and is a directory
 46→	info, err := os.Stat(path)
 47→	if err != nil {
 48→		return nil, fmt.Errorf("vault path error: %w", err)
 49→	}
 50→	if !info.IsDir() {
 51→		return nil, fmt.Errorf("vault path is not a directory: %s", path)
 52→	}
 53→
 54→	return &Vault{Path: path}, nil
 55→}
