 57→// IsPathAllowed checks if a given path is within the allowed vault directory
 58→// and doesn't access hidden files or directories
 59→func (v *Vault) IsPathAllowed(path string) (bool, error) {
 60→	// Expand home directory
 61→	if strings.HasPrefix(path, "~") {
 62→		home, err := os.UserHomeDir()
 63→		if err != nil {
 64→			return false, fmt.Errorf("failed to get home directory: %w", err)
 65→		}
 66→		path = filepath.Join(home, path[1:])
 67→	}
 68→
 69→	// Get absolute path
 70→	absPath, err := filepath.Abs(path)
 71→	if err != nil {
 72→		return false, fmt.Errorf("failed to get absolute path: %w", err)
 73→	}
 74→
 75→	// Resolve symlinks
 76→	resolvedPath, err := filepath.EvalSymlinks(absPath)
 77→	if err != nil {
 78→		// If the path doesn't exist, walk up to the nearest existing
 79→		// ancestor, resolve its symlinks, then re-append the remainder.
 80→		if os.IsNotExist(err) {
 81→			resolvedPath = resolveWithAncestors(absPath)
 82→		} else {
 83→			return false, fmt.Errorf("failed to resolve symlinks: %w", err)
 84→		}
 85→	}
 86→
 87→	// Get absolute vault path
 88→	absVaultPath, err := filepath.Abs(v.Path)
 89→	if err != nil {
 90→		return false, fmt.Errorf("failed to get absolute vault path: %w", err)
 91→	}
 92→
 93→	// Resolve vault symlinks
 94→	resolvedVaultPath, err := filepath.EvalSymlinks(absVaultPath)
 95→	if err != nil {
 96→		if !os.IsNotExist(err) {
 97→			return false, fmt.Errorf("failed to resolve vault symlinks: %w", err)
 98→		}
 99→		resolvedVaultPath = resolveWithAncestors(absVaultPath)
100→	}
101→
102→	// Clean paths
103→	cleanPath := filepath.Clean(resolvedPath)
104→	cleanVaultPath := filepath.Clean(resolvedVaultPath)
105→
106→	// Check if path is within vault (ensure separator boundary to prevent
107→	// prefix false-positives like /tmp/vault matching /tmp/vault-evil)
108→	if cleanPath != cleanVaultPath && !strings.HasPrefix(cleanPath, cleanVaultPath+string(filepath.Separator)) {
109→		return false, nil
110→	}
111→
112→	/

