 8→// Slugify converts a title string into a URL/filename-safe slug
 9→func Slugify(s string) string {
10→	var b strings.Builder
11→	prevHyphen := false
12→	for _, r := range strings.ToLower(s) {
13→		if unicode.IsLetter(r) || unicode.IsDigit(r) {
14→			b.WriteRune(r)
15→			prevHyphen = false
16→		} else if !prevHyphen && b.Len() > 0 {
17→			b.WriteByte('-')
18→			prevHyphen = true
19→		}
20→	}
21→	result := b.String()
22→	return strings.TrimRight(result, "-")
23→}
24→
25→// GenerateFrontmatter creates YAML frontmatter with tags and timestamps
26→func GenerateFrontmatter(tags []string, created, updated string) string {
27→	var b strings.Builder
28→	b.WriteString("---\n")
29→	if len(tags) > 0 {
30→		b.WriteString("tags:\n")
31→		for _, tag := range tags {
32→			b.WriteString("  - ")
33→			b.WriteString(tag)
34→			b.WriteByte('\n')
35→		}
36→	}
37→	b.WriteString("created: ")
38→	b.WriteString(created)
39→	b.WriteByte('\n')
40→	b.WriteString("updated: ")
41→	b.WriteString(updated)
42→	b.WriteByte('\n')
43→	b.WriteString("---\n")
44→	return b.String()
45→}
46→
47→// ParseFrontmatterTags parses tags from YAML frontmatter content (without delimiters)
48→func ParseFrontmatterTags(frontmatter string, tagCounts map[string]int) {
49→	lines := strings.Split(frontmatter, "\n")
50→	inTags := false
51→	for _, line := range lines {
52→		trimmed := strings.TrimSpace(line)
53→
54→		// Check for "tags:" header
55→		if trimmed == "tags:" {
56→			inTags = true
57→			continue
58→		}
59→
60→		// Check for inline tags: tags: [tag1, tag2]
61→		if after, ok := strings.CutPrefix(trimmed, "tags:"); ok {
62→			rest := strings.TrimSpace(after)
63→			if strings.HasPrefix(rest, "[") && strings.HasSuffix(rest, "]") {
64→				inner := rest[1 : len(rest)-1]
65→				for tag := range strings.SplitSeq(inner, ",") {
66→					tag = strings.TrimSpace(tag)
67→					if tag != "" {
68→						tagCounts[tag]++
69→					}
70→				}
71→			}
72→			inTags = false
73→			continue
74→		}
75→
76→		// Parse block-style tag list items
77→		if inTags {
78→			if after, ok := strings.CutPrefix(trimmed, "- "); ok {
79→				tag := strings.TrimSpace(after)
80→				if tag != "" {
81→					tagCounts[tag]++
82→				}
83→			} else if trimmed != "" {
84→				// No longer in tags block
85→				inTags = false
86→			}
87→		}
88→	}
89→}
